mapper.update:
update notification_deliveries
set status = 'dead',
    claimed_at = null,
    claimed_by = null,
    last_error = #{lastError}
where status = 'processing'
  and claimed_at <= #{claimDeadline}
  and exists (
      select 1
      from notifications
      where notifications.id = notification_deliveries.notification_id
        and notifications.created_at <= #{expiryCutoff}
  )

update notification_deliveries
set status = 'dead',
    claimed_at = null,
    claimed_by = null,
    last_error = #{lastError}
where status = 'processing'
  and claimed_at <= #{claimDeadline}
  and attempt_count >= #{maxAttempts}

update notification_deliveries
set status = #{status},
    next_attempt_at = #{nextAttemptAt},
    claimed_at = null,
    claimed_by = null,
    provider_message_id = null,
    last_error = #{lastError}
where id = #{deliveryId}
  and status = 'processing'
  and claimed_by = #{claimOwner}

update notification_deliveries
set status = 'dead',
    claimed_at = null,
    claimed_by = null,
    provider_message_id = null,
    last_error = #{lastError}
where id = #{deliveryId}
  and status = 'processing'
  and claimed_by = #{claimOwner}

update user_device_tokens
set enabled = false
where id = #{deviceTokenId}

update notification_deliveries
set status = 'dead',
    claimed_at = null,
    claimed_by = null,
    provider_message_id = null,
    last_error = #{lastError}
where device_token_id = #{deviceTokenId}
  and id <> #{deliveryId}
  and (
      status in ('pending', 'retry')
      or (status = 'processing' and claimed_by = #{claimOwner})
  )
